import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

const OptimizeVideo = () => {
  const location = useLocation();
  const [videoPath, setVideoPath] = useState("");
  const [message, setMessage] = useState("");
  const [videoType, setVideoType] = useState("");

  useEffect(() => {
    if (location.state) {
      const { videoURL, results = {} } = location.state;

      // Check for audio processing path first
      const audioProcessedPath = results.audio_processing?.enhanced_video_path;
      const videoOptimizedPath = results.video_upscaling?.output_path;

      // Determine which path to use
      const finalPath = audioProcessedPath || videoOptimizedPath;

      if (finalPath) {
        // Extract filename from the full path
        const filename = finalPath.split('\\').pop().split('/').pop();
        setVideoPath(`http://127.0.0.1:8000/media/${filename}`);
        setVideoType(audioProcessedPath ? 'Audio Enhanced' : 'Video Optimized');
      } else {
        setMessage("No processed video available");
      }
    }
  }, [location.state]);

  const handleDownload = () => {
    if (videoPath) {
      const link = document.createElement("a");
      link.href = videoPath;
      link.download = `optimized-video-${Date.now()}.mp4`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4">
      <Card>
        <CardHeader>
          <CardTitle>
            {videoType ? `${videoType} Video Output` : 'Video Output'}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {videoPath ? (
              <>
                <video
                  className="w-full rounded-lg shadow-lg"
                  controls
                  src={videoPath}
                >
                  Your browser does not support the video tag.
                </video>
                <div className="flex justify-end space-x-2">
                  <Button
                    onClick={handleDownload}
                    className="bg-blue-600 hover:bg-blue-700"
                  >
                    Download Video
                  </Button>
                </div>
              </>
            ) : (
              <div className="text-center p-8 bg-gray-100 rounded-lg">
                <p className="text-gray-600">
                  {message || "Loading video..."}
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default OptimizeVideo;
